function switchTab(e, tabId) {
        document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));
        document.querySelectorAll('.tab-btn').forEach(el => {
            el.classList.remove('active', 'border-blue-600', 'text-blue-600');
            el.classList.add('text-slate-500');
        });
        document.getElementById(tabId).classList.add('active');
        e.currentTarget.classList.remove('text-slate-500');
        e.currentTarget.classList.add('active', 'border-blue-600', 'text-blue-600');

        // 徹底修復 hidden 畫布無寬高像素之 Chart.js 原生缺陷
        if (tabId === 'financials') {
            if (window.charts.unhSegment) window.charts.unhSegment.resize();
            if (window.charts.unhProfit) window.charts.unhProfit.resize();
        } else if (tabId === 'valuation') {
            if (window.charts.unhValuation) window.charts.unhValuation.resize();
        }
    }

