functions.callGeminiAPI:
async function callGeminiAPI(prompt, systemInstruction) {
    try {
        const response = await fetch('/api/gemini', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ prompt: prompt, systemInstruction: systemInstruction })
        });
        const data = await response.json();
        if (!response.ok) return `連線錯誤：${data.error || '未知錯誤'}`;
        let rawText = data.candidates?.[0]?.content?.parts?.[0]?.text || "抱歉，無法產生有效回覆。";
        return rawText.replace(/\n/g, '<br>').replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
    } catch (error) { return `網路連線失敗。(${error.message})`; }
}

